inline constexpr char kSpriteFragmentMsl[] = R"msl(#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct fs_main_out
{
    float4 _entryPointOutput [[color(0)]];
};

struct fs_main_in
{
    float2 input_uv [[user(locn0)]];
    float4 input_color [[user(locn1)]];
};

fragment fs_main_out fs_main(fs_main_in in [[stage_in]], texture2d<float> sprite_texture [[texture(0)]], sampler sprite_textureSmplr [[sampler(0)]])
{
    fs_main_out out = {};
    out._entryPointOutput = sprite_texture.sample(sprite_textureSmplr, in.input_uv) * in.input_color;
    return out;
}

)msl";

inline constexpr char kSpriteFragmentGlsl[] = R"glsl(#version 300 es
precision highp float;
precision highp int;

uniform highp sampler2D sprite_texture;

in highp vec2 v_uv;
in highp vec4 v_color;
layout(location = 0) out highp vec4 _entryPointOutput;

void main()
{
    _entryPointOutput = texture(sprite_texture, v_uv) * v_color;
}

)glsl";

inline constexpr char kSpriteFragmentWgsl[] = R"wgsl(@group(2u) @binding(0u) var sprite_texture : texture_2d<f32>;

@group(2u) @binding(8u) var sprite_sampler : sampler;

var<private> v : vec4<f32>;

fn fs_main_inner(v_1 : vec2<f32>, v_2 : vec4<f32>) {
  v = (textureSample(sprite_texture, sprite_sampler, v_1) * v_2);
}

@fragment
fn fs_main(@location(0u) v_3 : vec2<f32>, @location(1u) v_4 : vec4<f32>) -> @location(0u) vec4<f32> {
  fs_main_inner(v_3, v_4);
  return v;
}
)wgsl";

inline constexpr char kSpriteHlsl[] = R"hlsl(// The 2D shader: triangles with a position in pixels, a texture coordinate and a color that
// multiplies the texture. Registers follow SDL's GPU conventions: vertex uniforms in space1,
// fragment textures and samplers in space2.

cbuffer View : register(b0, space1) {
    // Maps positions to clip space; column-major, so it multiplies column vectors.
    float4x4 view_projection;
};

struct VertexInput {
    float2 position : TEXCOORD0;
    float2 uv : TEXCOORD1;
    float4 color : TEXCOORD2;
};

struct VertexOutput {
    float2 uv : TEXCOORD0;
    float4 color : TEXCOORD1;
    float4 position : SV_Position;
};

VertexOutput vs_main(VertexInput input) {
    VertexOutput output;
    output.position = mul(view_projection, float4(input.position, 0.0, 1.0));
    output.uv = input.uv;
    output.color = input.color;
    return output;
}

Texture2D<float4> sprite_texture : register(t0, space2);
SamplerState sprite_sampler : register(s0, space2);

float4 fs_main(VertexOutput input) : SV_Target0 {
    return sprite_texture.Sample(sprite_sampler, input.uv) * input.color;
}
)hlsl";

